import type { Lane } from '../config/schema.js'

export type RiskZone = 'green' | 'yellow' | 'red'

export type DuplicateRisk = 'none' | 'low' | 'medium' | 'likely_duplicate'

export interface TaskSource {
  type: 'github_issue' | 'repo_signal' | 'integration_gap'
  id: string
  title: string
}

export interface TaskRecord {
  taskId: string
  source: TaskSource
  lane: Lane
  riskZone: RiskZone
  branchName: string
  prNumber: number | null
  expectedClasses: string[]
  duplicateRisk: DuplicateRisk
  abandoned: boolean
  createdAt: string
  notes: string[]
}

export interface TaskRegistry {
  nextTaskNumber: number
  tasks: Record<string, TaskRecord>
}

export const EMPTY_REGISTRY: TaskRegistry = {
  nextTaskNumber: 1,
  tasks: {},
}
